text:
/* Tokens are local to Contacts; the workspace theme and shell stay unchanged. */
.page {
  --contacts-bg: var(--background);
  --contacts-elevated: var(--card);
  --contacts-surface: var(--card);
  --contacts-inset: var(--surface);
  --contacts-border: var(--border);
  --contacts-strong: var(--border-hover);
  --contacts-text: var(--foreground);
  --contacts-muted: var(--muted-foreground);
  --contacts-purple: var(--link);
  --contacts-pink: var(--color-contacts-contacts-pink-1);
  --contacts-red: var(--status-error-text);
  --contacts-green: var(--status-success-text);
  --contacts-gradient: linear-gradient(
    135deg,
    var(--color-contacts-contacts-gradient-2),
    var(--color-contacts-contacts-pink-1)
  );
}
:global([data-theme="dark"]) .page {
  --contacts-bg: var(--color-contacts-contacts-bg-3);
  --contacts-elevated: var(--color-contacts-contacts-elevated-4);
  --contacts-surface: var(--color-contacts-contacts-surface-5);
  --contacts-inset: var(--color-contacts-contacts-inset-6);
  --contacts-border: var(--color-contacts-contacts-border-7);
  --contacts-strong: var(--color-contacts-contacts-strong-8);
  --contacts-text: var(--color-contacts-contacts-text-9);
  --contacts-muted: var(--color-contacts-contacts-muted-10);
  --contacts-purple: var(--contacts-readable-purple);
  --contacts-red: var(--color-contacts-contacts-red-11);
  --contacts-green: var(--color-contacts-contacts-green-12);
}
.page :is(input, textarea)::placeholder {
  color: var(--contacts-muted);
  opacity: 1;
}
.page :is(button, a, input, textarea, summary, [tabindex]):focus-visible {
  outline: 2px solid var(--contacts-pink);
  outline-offset: 3px;
}
.actions .secondary {
  transition:
    translate 180ms ease,
    filter 180ms ease,
    box-shadow 180ms ease,
    border-color 180ms ease,
    background-color 180ms ease;
}
@media (hover: hover) and (pointer: fine) {
  .actions .secondary:hover,
  .shortlistTrigger:hover button:not([aria-busy="true"]) {
    translate: 0 -2px;
    border-color: var(--contacts-purple);
    filter: var(--button-hover-filter);
  }
  .actions .secondary:active,
  .shortlistTrigger:active button:not(:disabled) {
    translate: 0 0;
  }
}
.page button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}
.actions :is(button, a) {
  border-radius: 999px;
}
.import :is(input:not([type="file"]), textarea) {
  border-radius: var(--appearance-radius, 14px);
  border-color: var(--contacts-border);
  background: var(--contacts-inset);
  color: var(--contacts-text);
}
.import input:not([type="file"]) {
  min-height: 46px;
}
.import button {
  border-radius: 999px;
  border-color: var(--contacts-strong);
}
.import :is(input, textarea)[aria-invalid="true"] {
  border-color: var(--contacts-red);
}
.import :global(.text-body) {
  color: var(--contacts-muted);
}
@media (prefers-reduced-motion: reduce) {
  .page *,
  .page *::before,
  .page *::after {
    animation: none !important;
    transition: none !important;
    scroll-behavior: auto !important;
  }
}

:global(html[data-workspace][data-appearance="vercel"]) .page {
  --contacts-bg: var(--background);
  --contacts-elevated: var(--card);
  --contacts-surface: var(--card);
  --contacts-inset: var(--surface);
  --contacts-border: var(--border);
  --contacts-strong: var(--border-hover);
  --contacts-text: var(--foreground);
  --contacts-muted: var(--body);
  --contacts-purple: var(--link);
  --contacts-pink: var(--ring);
  --contacts-red: var(--status-error-text);
  --contacts-green: var(--status-success-text);
  --contacts-gradient: linear-gradient(var(--foreground), var(--foreground));
}
:global(html[data-workspace][data-appearance="vercel"])
  :is(.primary, .secondary) {
  border-radius: var(--appearance-control-radius);
}
:global(html[data-workspace][data-appearance="vercel"])
  :is(.actions, .import)
  :is(button, a) {
  border-radius: var(--appearance-control-radius);
}

:global(html[data-workspace][data-appearance="vercel"]) .roleBadge {
  border: 1px solid var(--highlight-border);
  border-radius: var(--appearance-badge-radius);
  background: var(--highlight-background);
  color: var(--highlight-foreground);
}

/* Contacts layout refinements are limited to the Vercel appearance. */
:global(html[data-workspace][data-appearance="vercel"]) .company {
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
}
:global(html[data-workspace][data-appearance="vercel"]) .expandControl button {
  width: 32px;
  height: 32px;
  min-height: 32px;
}
:global(html[data-workspace][data-appearance="vercel"])
  .contactRow
  .actions
  :is(button, a) {
  min-height: 36px;
  height: 36px;
  padding: 6px 10px;
  font-size: 12px;
}
:global(html[data-workspace][data-appearance="vercel"])
  .contactRow
  .shortlistTrigger
  button {
  width: 36px;
  padding: 8px;
}
:global(html[data-workspace][data-appearance="vercel"]) .contactForm > * {
  grid-column: 1 / -1;
  min-width: 0;
  margin-block: 0;
}
:global(html[data-workspace][data-appearance="vercel"])
  .contactForm
  > [data-contact-field="name"],
:global(html[data-workspace][data-appearance="vercel"])
  .contactForm
  > [data-contact-field="company"] {
  grid-column: span 1;
}
:global(html[data-workspace][data-appearance="vercel"])
  .contactForm
  > [role="status"]:empty {
  display: none;
}
@media (max-width: 479px) {
  :global(html[data-workspace][data-appearance="vercel"])
    .contactForm
    > [data-contact-field] {
    grid-column: 1 / -1;
  }
}
